ws = openpyxl.load_workbook(X, data_only=True)['Наименования и артикулы']
rows = [r for r in ws.iter_rows(min_row=6, values_only=True) if r[0] and r[1]]
E = html.escape
def norm(s): return str(s).replace('.', ',').replace(' ', '').replace('–', '–')
proj = collections.OrderedDict()
for r in rows:
    key = (r[1], norm(r[2])); proj.setdefault(key, []); w = str(r[3]).replace('–', '–')
    if w not in proj[key]: proj[key].append(w)
proj = collections.OrderedDict(sorted(proj.items(), key=lambda kv: float(kv[0][1].replace(',', '.'))))
prow = ''.join(f'<tr><td class=mono>{E(k[0])}</td><td class=mono>{E(k[1])}</td><td class=mono>{E("; ".join(v))}</td><td class=mono>ПБС.{E(k[0])}.01…</td></tr>' for k, v in proj.items())
